const cleanText = (value) => String(value ?? "").replace(/\\n/g, "\n").replace(/\r/g, "").trim();
const normalized = (value) => cleanText(value).normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").toLowerCase();
const digits = (value) => Number(String(value ?? "").replace(/[^\d]/g, "")) || 0;
const isPresent = (value) => cleanText(value) && cleanText(value) !== "0";

const parseCsv = (csv) => {
  const rows = csv.trim().split(/\r?\n/).map((line) => line.match(/(?:^|,)(?:"((?:[^"]|"")*)"|([^",]*))/g)
