};

const getPriceMaster = async () => {
  const state = $getWorkflowStaticData("global");
  const cached = state.priceMasterCache;
  const now = Date.now();
  if (cached?.rows?.length && now - cached.at < 300000) return mergePriceMaster(cached.rows);
  try {
    const response = await fetch(PRICE_MASTER_URL);
    if (!response.ok) throw new Error("Không tải được bảng giá");
    const rows = parseCsv(await response.text()).filter((row) => row.active === "TRUE");
    if (!rows.length) throw new Error("Bảng giá không có dòng đang áp dụng");
    state.priceMasterCache = { at: now, rows };
    return mergePriceMaster(rows);
  } catch {
    return mergePriceMaster(cached?.rows || []);
  }
};

const productCode = (product) => {
