  if (name.includes("cacao") || name.includes("tropical")) return "CACAO300";
  if (name.includes("combo 10") && name.includes("mix")) return "COMBO10_MIX";
  if (name.includes("combo 10") && name.includes("xanh")) return "COMBO10_XANH";
  if (name.includes("combo 10") && name.includes("nau")) return "COMBO10_NAU";
  if (name.includes("combo 10") && name.includes("cam")) return "COMBO10_CAM";
  if (name.includes("xanh")) return "XANH";
  if (name.includes("vang")) return "VANG";
  if (name.includes("nau")) return "NAU";
  return "";
};

const orderKey = (items) => {
  const counts = items.reduce((result, item) => ({ ...result, [item.code]: (result[item.code] || 0) + item.quantity }), {});
  const codes = Object.keys(counts);
  if (!codes.length || codes.some((code) => !code || counts[code] < 1 || counts[code] > 3)) return "";
  if (codes.length === 1 && ["CACAO300", "COMBO10_MIX", "COMBO10_XANH", "COMBO10_NAU", "COMBO10_CAM"].includes(codes[0])) return codes[0] + "=" + counts[codes[0]];
  if (codes.some((code) => !["XANH", "VANG", "NAU"].includes(code))) return "";
  return ["XANH", "VANG", "NAU"].filter((code) => counts[code]).map((code) => code + "=" + counts[code]).join("|");
};

