let xungHo = "bạn"; // mặc định khi chưa xác định được giới tính
const genderMatch = query.match(/(?:Khách hàng có\s*)?giới tính là\s*([a-zA-Z]+)\s*\.?/i);
if (genderMatch) {
  const g = genderMatch[1].toLowerCase();
  if (g === 'male') xungHo = "anh";
  if (g === 'female') xungHo = "chị";
}

// 2. NHẬN DIỆN SỐ ĐIỆN THOẠI
let phone = "";
const normalized = query.replace(/(\d)[\s.\-()]+(\d)/g, "$1$2");
const numberGroups = normalized.match(/\+?\d+/g) || [];
const vnCarrierPrefixRegex = /^0(3[2-9]|5[25689]|7[06-9]|8[1-9]|9[0-46-9])\d{7}$/;
for (let group of numberGroups) {
  let raw = group.startsWith("+84") ? "0" + group.slice(3) :
           (group.startsWith("84") && group.length === 11 ? "0" + group.slice(2) : group);

  if (vnCarrierPrefixRegex.test(raw)) {
    phone = raw;
    break;
  }
}

// 3. TRẢ KẾT QUẢ
return [{
  json: {
    phone: phone,
    xungHo: xungHo
  }
}];

// Bóc tách nguồn tin để phân biệt chính xác bình luận và inbox.
