const extract = (regex) => {
  const match = rawQuery.match(regex);
  return match ? match[1].trim() : "";
};

const customerComment = extract(/Bình luận của khách:\s*([\s\S]*?)(?=Tin nhắn gần nhất của Page:|Nội dung tin nhắn của Khách:|$)/);
const customerMessage = extract(/Nội dung tin nhắn của Khách:\s*([\s\S]*?)(?=\n\s*Phân loại bình luận:|$)/);

// "Phân loại bình luận" có cả ở inbox nên không dùng trường này để nhận diện kênh.
const isComment = customerComment.length > 0;

return [{
